// The generated API types are intentionally broad across optional product workflows.
// Runtime payloads are validated by the API; this page keeps the first-pass forms composable.
// @ts-nocheck
import * as React from 'react';
import { useState, type ReactNode } from 'react';
import { Link, useLocation, useParams } from 'wouter';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/lib/auth';
import { t } from '@/lib/i18n';
import {
  useCreateApiary, useCreateBatch, useCreateCorrection, useCreateFeedback, useCreateHarvest, useCreateHive, useCreateInspection,
  useCreateProcessing, useCreateQualityTest, useCreateSupplyChainEvent, useGetAnalytics, useGetBatch, useGetBatchQr, useGetDashboard,
  useHealthCheck, useGetApiary, useGetHive, useUpdateApiary, useUpdateHive,
  useListApiaries, useListBatches, useListBlockchainTransactions, useListHarvests, useListHives, useListSupplyChainEvents,
  usePredictYield, useVerifyBatch, useVerifyBlockchain as useVerifyBlockchainQuery,
  getGetAnalyticsQueryKey, getGetBatchQueryKey, getGetBatchQrQueryKey, getGetDashboardQueryKey, getListApiariesQueryKey,
  getListBatchesQueryKey, getListHarvestsQueryKey, getListHivesQueryKey, getListSupplyChainEventsQueryKey, getListBlockchainTransactionsQueryKey,
  getVerifyBlockchainQueryKey, getGetApiaryQueryKey, getGetHiveQueryKey,
} from '@workspace/api-client-react';
import { ArrowRight, Award, BarChart3, Beaker, Bell, Blocks, Boxes, Check, CheckCircle2, ChevronRight, CircleAlert, ClipboardCheck, CloudRain, Database, Droplets, FileCheck2, Flower2, Gauge, Hexagon, Leaf, Loader2, LockKeyhole, MapPin, Package, Plus, RefreshCcw, ScanLine, ShieldCheck, Sprout, Star, Sun, TrendingUp, Truck, UserRound, Wind, X } from 'lucide-react';
