import { AppShell, PublicHeader } from '@/components/app-shell';

type AnyRecord = Record<string, any>;

function useVerifyBlockchain() {
  const query = useVerifyBlockchainQuery({ query: { queryKey: getVerifyBlockchainQueryKey(), enabled: false } });
  return { ...query, isPending: query.isFetching, mutate: (_value?: unknown, options?: AnyRecord) => query.refetch().then((result) => options?.onSuccess?.(result.data)) };
}

const prettyDate = (value?: string) => value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : 'Not recorded';
const number = (value?: number) => typeof value === 'number' ? value.toLocaleString(undefined, { maximumFractionDigits: 1 }) : '—';

function PageHead({ eyebrow, title, detail, action, actionLabel = 'Add record' }: { eyebrow: string; title: string; detail: string; action?: () => void; actionLabel?: string }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
    <div><p className="mb-2 font-mono-ui text-[10px] uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="font-display text-4xl font-bold tracking-tight text-foreground sm:text-5xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">{detail}</p></div>
    {action && <Button onClick={action} data-testid="button-page-action" className="shrink-0 rounded-xl px-5"><Plus className="size-4" />{actionLabel}</Button>}
  </div>;
}

function SectionLabel({ children }: { children: ReactNode }) { return <p className="font-mono-ui text-[10px] uppercase tracking-[.18em] text-muted-foreground">{children}</p>; }
function StatusPill({ value, good = false }: { value?: string; good?: boolean }) { const positive = good || ['verified', 'active', 'passed', 'complete', 'healthy', 'approved'].some((x) => value?.toLowerCase().includes(x)); return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 font-mono-ui text-[10px] uppercase tracking-wide ${positive ? 'border-emerald-700/20 bg-emerald-700/10 text-emerald-800 dark:text-emerald-300' : 'border-primary/20 bg-primary/10 text-primary-foreground'}`}><span className={`size-1.5 rounded-full ${positive ? 'bg-emerald-600' : 'bg-primary'}`} />{value ?? 'Pending'}</span>; }
function LoadingRows() { return <div className="space-y-3">{[1, 2, 3].map((i) => <div key={i} className="h-16 animate-pulse rounded-2xl bg-muted" />)}</div>; }
function EmptyState({ title, detail, onAdd }: { title: string; detail: string; onAdd?: () => void }) { return <div className="grid min-h-[260px] place-items-center rounded-2xl border border-dashed border-border bg-card/60 p-8 text-center"><div><span className="mx-auto mb-4 grid size-12 place-items-center rounded-2xl bg-primary/12 text-primary"><Leaf className="size-5" /></span><h3 className="font-display text-xl font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground">{detail}</p>{onAdd && <Button onClick={onAdd} variant="outline" className="mt-5 rounded-xl" data-testid="button-empty-add"><Plus className="size-4" />Add the first record</Button>}</div></div>; }
function ErrorState({ retry }: { retry: () => void }) { return <div className="rounded-2xl border border-destructive/20 bg-destructive/5 p-6"><div className="flex items-center gap-3 text-destructive"><CircleAlert className="size-5" /><p className="font-semibold">The notebook could not be opened.</p></div><p className="mt-2 text-sm text-muted-foreground">Check your connection and try again. Your records are safe.</p><Button variant="outline" onClick={retry} className="mt-4 rounded-xl" data-testid="button-retry"><RefreshCcw className="size-4" />Try again</Button></div>; }
function Drawer({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-50 flex items-end justify-end bg-foreground/35 sm:items-stretch"><div className="app-enter flex h-[92dvh] w-full flex-col overflow-y-auto rounded-t-3xl bg-card p-6 shadow-2xl sm:h-full sm:max-w-xl sm:rounded-none sm:rounded-l-3xl sm:p-8"><div className="mb-7 flex items-start justify-between"><div><SectionLabel>New field note</SectionLabel><h2 className="mt-2 font-display text-3xl font-bold">{title}</h2></div><button type="button" onClick={onClose} className="rounded-xl p-2 text-muted-foreground hover:bg-muted" data-testid="button-close-drawer"><X className="size-5" /></button></div>{children}</div></div>; }
function Field({ label, name, type = 'text', required = false, placeholder, value, onChange }: { label: string; name: string; type?: string; required?: boolean; placeholder?: string; value: string | number; onChange: (value: string) => void }) { return <label className="block space-y-2"><span className="text-xs font-semibold text-foreground">{label}{required && <span className="ml-1 text-primary">*</span>}</span><Input data-testid={`input-${name}`} name={name} type={type} required={required} placeholder={placeholder} value={value} onChange={(e) => onChange(e.target.value)} /></label>; }
function SaveButton({ pending, children = 'Save field note' }: { pending: boolean; children?: ReactNode }) { return <Button disabled={pending} className="w-full rounded-xl py-3" data-testid="button-save"><>{pending && <Loader2 className="size-4 animate-spin" />}</>{children}</Button>; }

